int main(int argc,char**argv)try{if(argc!=2)return 2;const std::filesystem::path out=argv[1];
 auto s=fixture(false);const auto original=s.encode();const auto target_id=s.active().id;const auto saved=*s.active().deformation;auto rest=saved;rest.pose.clear();rest.morph_weights.assign(rest.morphs->targets.size(),0);s.set_deformation(target_id,rest);auto high=s.active().painted->mesh();for(auto &v:high.positions){v.x*=2;v.y*=2;v.z=.15f;}for(size_t v=0;v<high.normals.size();++v)high.normals[v]=normalized(Vec3{high.positions[v].x*.2f,high.positions[v].y*.15f,1});const auto id=s.add("Real normal-detail source",Volume{});auto &o=s.object(id);o.mesh_active=true;o.visible=false;o.locked=true;o.painted=std::make_shared<PaintedMesh>(high,64);s.select(target_id);ObjectBakeSettings settings;settings.prepare_normals=true;settings.front_mm=500;settings.back_mm=50;settings.ao_samples=1;settings.padding=2;auto report=bake_object(s,id,settings);check(report.normal_prepared&&report.projected>0&&s.active().painted->normal_projection()&&s.active().painted->baked(),"Actual Bake authenticates a prepared intrinsic normal field and positive normal detail");
 auto live=*s.active().deformation;live.pose=saved.pose;live.morph_weights=saved.morph_weights;s.set_deformation(target_id,live);const auto detail=s.active().painted->baked();uint8_t low=255,top=0;for(size_t i=0;i<detail->coverage.size();++i)if(detail->coverage[i]){low=std::min(low,detail->maps.normal.rgba[i*4]);top=std::max(top,detail->maps.normal.rgba[i*4]);}check(top>low+8,"Real positive baked detail has a nonconstant normal field");ShapeKeyEdit edit;edit.action=ShapeKeyAction::Replace;edit.target=0;edit.positions=s.active().painted->mesh().positions;edit.positions[0].z+=.013f;edit.positions[3].z-=.017f;author_shapekey(s,target_id,edit);const auto before=s;const auto paint=s.active().painted->encode();ShapeKeyEdit mirror;mirror.action=ShapeKeyAction::Mirror;mirror.target=0;mirror.name="Prepared source Mirror";author_shapekey(s,target_id,mirror);check(s.active().painted->encode()==paint,"Prepared Mirror preserves every intrinsic/detail/current Paint byte");check(s.active().material_bindings->normal_preparation->key_derivation==s.active().material_bindings->key_derivation,"Prepared Mirror recipe owns its actual new frame key node");const auto encoded=s.encode();check(encoded.at("version")==22&&encoded.at("source_materials").at("version")==10&&encoded.at("source_materials").at("normal_preparations").back().at("version")==5&&encoded.at("source_materials").at("key_derivations").back().at("version")==3,"Actual writer emits only genuine Scene22/material10/paired-normal5/Mirror3 capabilities");auto read=Scene::decode(encoded);check(read.encode()==encoded,"Actual paired normal-entry5/Mirror3 owning Scene roundtrip");std::filesystem::create_directories(out);before.save(out/"before.dsculpt");s.save(out/"after.dsculpt");ShapeKeyEdit restore;restore.action=ShapeKeyAction::Restore;author_shapekey(read,target_id,restore);check(read.encode()==before.encode(),"Prepared Mirror Restore retains full before-normal, source and Bake history");check(original==fixture(false).encode(),"Detached prepared workflow does not rewrite its actual original provided source");Document doc;doc.replace(before);auto done=[&]{if(!doc.wait_asset(std::chrono::seconds(120))||!doc.wait_mesh(std::chrono::seconds(120))||!doc.frame().state->error.empty())throw std::runtime_error("Prepared Mirror worker: "+doc.frame().state->error);};done();doc.author_shape(mirror);done();check(doc.copy_scene().encode()==encoded&&doc.undo()&&doc.copy_scene().encode()==before.encode()&&doc.redo()&&doc.copy_scene().encode()==encoded,"Actual prepared Mirror worker and one Undo/Redo retain exact field/detail/pose/history");
 doc.save(out/"native-after.dsculpt");check(Scene::load(out/"native-after.dsculpt").encode()==encoded,"Actual accepted native Mirror Save reopens the entire prepared graph");doc.replace(before);done();const auto file=out/"late-cancel.dsculpt";doc.save(file);const auto undo=doc.frame().state->can_undo,redo=doc.frame().state->can_redo;auto gate=std::make_shared<mirror_gate::Gate>();mirror_gate::Release release{gate};auto ready=gate->computed.get_future();{std::lock_guard lock(mirror_gate::mutex);mirror_gate::pending=gate;}doc.author_shape(mirror);check(ready.wait_for(std::chrono::seconds(120))==std::future_status::ready&&gate->changed,"Genuine prepared Mirror completes before test-only native publication gate");auto queued=doc.save_async(file);check(queued.wait_for(std::chrono::milliseconds(20))!=std::future_status::ready,"Actual queued Save waits behind prepared Mirror");doc.cancel_background_work();release.release();check(queued.wait_for(std::chrono::seconds(120))==std::future_status::ready&&refuses([&]{queued.get();},"cancel"),"Late native prepared Mirror cancellation reports real dependent Save failure");check(doc.wait_asset(std::chrono::seconds(120))&&doc.wait_mesh(std::chrono::seconds(120))&&doc.copy_scene().encode()==before.encode()&&Scene::load(file).encode()==before.encode()&&doc.frame().state->can_undo==undo&&doc.frame().state->can_redo==redo,"Late prepared Mirror Cancel preserves exact Scene/native file/global history");doc.author_shape(mirror);done();check(doc.copy_scene().encode()==encoded,"Native prepared Mirror retries exactly after cancellation");
 std::cout<<"PASS "<<checks<<" prepared Mirror worker checks\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}
